-- Chike's Creative Space - Robo Math Buddy on the Play page, for subscribers only (like Gravity 4 and Pic-a-Puzzle).
-- Safe to re-run. Nothing here sends an email.
--
-- The game's code is not a public file: it lives in the admin-only portal_game_files table (row pg-math-robot,
-- source supabase/private-games/math-robot.html), handed out only to signed-in subscribers as the example at the
-- top of AI Lesson 03 (supabase/ai-lesson-math-robot.sql). This row only puts a card with a lock on the Play page;
-- its page sends visitors to that lesson, where the portal's own gate asks them to join first.
-- The card's picture is the game's own screen (assets/games/robo-math-buddy.jpg), not a photo.

insert into games (id, data) values ('game-robo-math-buddy', $j${"id":"game-robo-math-buddy","title":"Robo Math Buddy","slug":"robo-math-buddy","kind":"members","summary":"Chat with a 3D robot that shows the math, step by step.","players":"1","minutes":10,"ageMin":5,"ageMax":11,"rules":["Tell the robot your first name or a nickname, and your grade (K to 5).","Ask a math question, like 12 times 8 or 15 plus 27. The robot works it out on the board, one step at a time.","Look at the board: balls to count, pies cut into equal slices, and hundreds, tens and ones blocks help you see the math.","Homework help: type one problem. The robot shows the steps and leaves the last one for you to finish.","Say Quiz me! for a question that fits your grade. After each answer, you choose whether to keep going.","Get 3 right in a row, then tap the robot's raised hand for a high five!","Press the Voice button to hear the robot talk, or the microphone button to talk to it. You can always type instead."],"leadsTo":"","interactive":true,"path":"","icon":"bot","p1":"#CFF1F7","p2":"#0E7490","status":"published","featured":false,"badge":"New","order":0,"vocabWord":"sum","vocabSay":"SUM · noun","vocabMeaning":"The number you get when you add numbers together.","vocabExample":"In Robo Math Buddy, 8 + 5 makes a sum of 13. Count the balls on the board to check!","createdAt":"2026-11-02T12:00:00.000Z","updatedAt":"2026-11-02T12:00:00.000Z","cover":{"src":"assets/games/robo-math-buddy.jpg","alt":"Robo Math Buddy's screen: a chat on the left, and a white 3D robot under a whiteboard that shows 8 + 5 with 8 blue balls and 5 orange balls"},"portalSlug":"how-to-build-your-own-math-robot"}$j$::jsonb)
on conflict (id) do update set data = excluded.data, updated_at = now();
